import { supabase } from "@/integrations/supabase/client";
import type { CodePatch, RepoFile, RepoTarget, SastFinding, ThreatModel, ValidatedFinding } from "./types";

export type AgentAnalysisResult = {
  riskScore: number;
  summary: string;
  validatedFindings: ValidatedFinding[];
  falsePositivesRemoved: number;
  threatModel?: ThreatModel;
  patches: CodePatch[];
  prTitle: string;
  prBody: string;
  complianceNotes: string[];
  /** llm = Groq edge function; rule-based = SAST confidence only (no LLM) */
  analysisMode?: "llm" | "rule-based";
  model?: string;
};

export async function invokeSecurityAgent(body: {
  mode: "triage" | "patches" | "full";
  target: RepoTarget;
  files: RepoFile[];
  sastFindings: SastFinding[];
  threatModel?: ThreatModel;
  validatedFindings?: ValidatedFinding[];
}): Promise<AgentAnalysisResult> {
  const { data, error } = await supabase.functions.invoke("ai-security-agent", { body });

  if (error) {
    throw new Error(error.message ?? "Security agent request failed");
  }
  if (data?.error) {
    throw new Error(String(data.error));
  }

  return data as AgentAnalysisResult;
}

/** Rule-based fallback when the LLM edge function is unavailable — never claims AI reasoning. */
export function offlineTriage(findings: SastFinding[]): AgentAnalysisResult {
  const validated: ValidatedFinding[] = findings.map((f) => ({
    ...f,
    validated: f.confidence !== "low",
    falsePositive: f.confidence === "low",
    rootCause: `SAST rule ${f.ruleId} matched in ${f.file}`,
    exploitability: f.severity === "critical" || f.severity === "high" ? "Review required" : "Context-dependent",
    recommendation: `Review ${f.file}:${f.line} — ${f.title}`,
  }));

  const active = validated.filter((f) => !f.falsePositive);
  const riskScore = Math.min(100, active.reduce((s, f) => {
    const w = { critical: 25, high: 15, medium: 8, low: 3, info: 1 };
    return s + (w[f.severity] ?? 0);
  }, 0));

  return {
    riskScore,
    summary: `Rule-based triage only (LLM unavailable): ${active.length} finding(s) from SAST across ${new Set(active.map((f) => f.file)).size} file(s). Low-confidence matches marked as false positives. Re-run when ai-security-agent is reachable for LLM verification and patches.`,
    validatedFindings: validated,
    falsePositivesRemoved: validated.filter((f) => f.falsePositive).length,
    patches: [],
    prTitle: `security: review ${active.length} SAST finding(s)`,
    prBody: buildOfflinePrBody(active),
    complianceNotes: ["SAST completed", "Rule-based triage — no LLM inference"],
    analysisMode: "rule-based",
    model: "sast-rules",
  };
}

function buildOfflinePrBody(findings: ValidatedFinding[]): string {
  const lines = findings.slice(0, 15).map(
    (f) => `- [${f.severity.toUpperCase()}] **${f.title}** (\`${f.file}:${f.line}\`)\n  ${f.recommendation}`,
  );
  return `## Security remediation (ThreatLens SAST)

${lines.join("\n\n")}

---
*Rule-based report — SAST findings only. LLM triage not used.*
`;
}

export function buildPrMarkdown(
  target: RepoTarget,
  summary: string,
  findings: ValidatedFinding[],
  patches: CodePatch[],
  riskScore: number,
): { title: string; body: string } {
  const title = `security: AI-engineer remediation (${findings.filter((f) => !f.falsePositive).length} findings, risk ${riskScore}/100)`;

  const findingSection = findings
    .filter((f) => !f.falsePositive)
    .slice(0, 20)
    .map((f) => `### ${f.title}
- **Severity:** ${f.severity} | **File:** \`${f.file}:${f.line}\`
- **Root cause:** ${f.rootCause ?? "See analysis"}
- **Fix:** ${f.recommendation}
${f.cwe ? `- **CWE:** ${f.cwe}` : ""}`)
    .join("\n\n");

  const patchSection = patches.slice(0, 10).map((p) => `### ${p.title} (\`${p.file}\`)
${p.description}

\`\`\`diff
${p.diff}
\`\`\`
`).join("\n");

  const body = `## Summary
${summary}

**Risk score:** ${riskScore}/100  
**Repository:** ${target.url}

## Validated findings
${findingSection || "_No critical findings after triage._"}

## Proposed patches
${patchSection || "_No automatic patches generated._"}

## Compliance evidence
- Static analysis (SAST) completed
- LLM-assisted false positive reduction
- Remediation patches included for developer review

---
*Autonomous scan by [ThreatLens AI Security Engineer](${target.url})*
`;

  return { title, body };
}
