import { cn } from "@/lib/utils";
import { CheckCircle2, Circle, Loader2, AlertCircle } from "lucide-react";
import type { AgentWorkflowStep, ScanPhase } from "@/lib/ai-assessment/types";
import { WORKFLOW_STEPS } from "@/lib/ai-assessment/types";

const PHASE_ORDER: ScanPhase[] = [
  "discover", "sast", "threat-model", "llm-triage", "generate-fixes", "complete",
];

function phaseIndex(phase: ScanPhase): number {
  if (phase === "idle" || phase === "error") return -1;
  if (phase === "clone") return 0;
  const idx = PHASE_ORDER.indexOf(phase);
  return idx >= 0 ? idx : PHASE_ORDER.length;
}

export function WorkflowStepper({ phase, steps = WORKFLOW_STEPS }: { phase: ScanPhase; steps?: AgentWorkflowStep[] }) {
  const current = phaseIndex(phase);
  const isError = phase === "error";

  return (
    <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
      {steps.map((step, i) => {
        const done = current > i || phase === "complete";
        const active = current === i && !isError && phase !== "complete";
        const failed = isError && current === i;

        return (
          <div
            key={step.id}
            className={cn(
              "rounded-xl border p-4 transition-all",
              done && "border-emerald-500/30 bg-emerald-500/5",
              active && "border-orange-500/40 bg-orange-500/5 shadow-[0_0_20px_rgba(249,115,22,0.08)]",
              failed && "border-red-500/40 bg-red-500/5",
              !done && !active && !failed && "border-white/5 bg-white/[0.02]",
            )}
          >
            <div className="flex items-start gap-3">
              <div className="mt-0.5 shrink-0">
                {done ? (
                  <CheckCircle2 className="h-5 w-5 text-emerald-400" />
                ) : active ? (
                  <Loader2 className="h-5 w-5 text-orange-400 animate-spin" />
                ) : failed ? (
                  <AlertCircle className="h-5 w-5 text-red-400" />
                ) : (
                  <Circle className="h-5 w-5 text-slate-600" />
                )}
              </div>
              <div>
                <p className={cn("text-sm font-medium", done ? "text-emerald-300" : active ? "text-orange-300" : "text-slate-400")}>
                  {step.label}
                </p>
                <p className="text-xs text-slate-500 mt-0.5">{step.description}</p>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}
