import type { RepoFile, SastFinding, FindingSeverity } from "./types";

type Rule = {
  id: string;
  title: string;
  category: string;
  severity: FindingSeverity;
  cwe?: string;
  owasp?: string;
  pattern: RegExp;
  message: string;
  confidence: "high" | "medium" | "low";
  /** Skip if line matches (e.g. comments, test files) */
  skipLine?: RegExp;
};

