const DEP_VULN_HINTS: { pkg: string; below: string; severity: FindingSeverity; cve: string }[] = [
  { pkg: "lodash", below: "4.17.21", severity: "high", cve: "CVE-2021-23337" },
  { pkg: "axios", below: "1.6.0", severity: "medium", cve: "CVE-2023-45857" },
  { pkg: "express", below: "4.19.0", severity: "medium", cve: "Multiple" },
  { pkg: "jsonwebtoken", below: "9.0.0", severity: "high", cve: "CVE-2022-23529" },
  { pkg: "minimist", below: "1.2.6", severity: "medium", cve: "CVE-2021-44906" },
];

function uid() {
  return crypto.randomUUID?.() ?? `f-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

function lineNumber(content: string, index: number): number {
  return content.slice(0, index).split("\n").length;
}

function snippet(content: string, line: number): string {
  const lines = content.split("\n");
  const start = Math.max(0, line - 2);
  return lines.slice(start, start + 3).join("\n").slice(0, 200);
}

function semverLt(a: string, b: string): boolean {
  const pa = a.replace(/^[\^~]/, "").split(".").map(Number);
  const pb = b.split(".").map(Number);
  for (let i = 0; i < 3; i++) {
    if ((pa[i] ?? 0) < (pb[i] ?? 0)) return true;
    if ((pa[i] ?? 0) > (pb[i] ?? 0)) return false;
  }
  return false;
}

function scanDependencies(files: RepoFile[]): SastFinding[] {
  const pkg = files.find((f) => f.path.endsWith("package.json"));
  if (!pkg) return [];
  try {
    const json = JSON.parse(pkg.content);
    const deps = { ...json.dependencies, ...json.devDependencies };
    const findings: SastFinding[] = [];
    for (const hint of DEP_VULN_HINTS) {
      const ver = deps[hint.pkg];
      if (ver && semverLt(String(ver), hint.below)) {
        findings.push({
          id: uid(),
          ruleId: "DEP001",
          title: `Vulnerable dependency: ${hint.pkg}@${ver}`,
          severity: hint.severity,
          file: "package.json",
          line: 1,
          snippet: `"${hint.pkg}": "${ver}"`,
          category: "Dependencies",
          cwe: "CWE-1395",
          owasp: "A06:2021",
          confidence: "high",
        });
      }
    }
    return findings;
  } catch {
    return [];
  }
}

export function runSast(files: RepoFile[]): SastFinding[] {
  const findings: SastFinding[] = [];
  const seen = new Set<string>();

  for (const file of files) {
    if (file.path.includes(".test.") || file.path.includes(".spec.") || file.path.includes("__tests__")) {
      continue;
    }

    for (const rule of RULES) {
      rule.pattern.lastIndex = 0;
      let match: RegExpExecArray | null;
      while ((match = rule.pattern.exec(file.content)) !== null) {
        const line = lineNumber(file.content, match.index);
        const lineText = file.content.split("\n")[line - 1] ?? "";
        if (rule.skipLine?.test(lineText)) continue;

        const key = `${rule.id}:${file.path}:${line}`;
        if (seen.has(key)) continue;
        seen.add(key);

        findings.push({
          id: uid(),
          ruleId: rule.id,
          title: rule.title,
          severity: rule.severity,
          file: file.path,
          line,
          snippet: snippet(file.content, line),
          category: rule.category,
          cwe: rule.cwe,
          owasp: rule.owasp,
          confidence: rule.confidence,
        });
      }
    }
  }

  findings.push(...scanDependencies(files));

  const order: FindingSeverity[] = ["critical", "high", "medium", "low", "info"];
  return findings.sort((a, b) => order.indexOf(a.severity) - order.indexOf(b.severity));
}

export function computeRiskScore(findings: { severity: FindingSeverity; falsePositive?: boolean }[]): number {
  const weights: Record<FindingSeverity, number> = {
    critical: 25, high: 15, medium: 8, low: 3, info: 1,
  };
  let score = 0;
  for (const f of findings) {
    if (f.falsePositive) continue;
    score += weights[f.severity] ?? 0;
  }
  return Math.min(100, score);
}
