import type { RepoFile, RepoTarget, SastFinding, ThreatModel } from "./types";

export function buildThreatModel(
  target: RepoTarget,
  files: RepoFile[],
  findings: SastFinding[],
): ThreatModel {
  const assets = inferAssets(target, files);
  const attackSurfaces = inferAttackSurfaces(files, findings);
  const attackPaths = buildAttackPaths(findings, attackSurfaces);
  const prioritizedRisks = prioritizeRisks(findings);

  return { assets, attackSurfaces, attackPaths, prioritizedRisks };
}

function inferAssets(target: RepoTarget, files: RepoFile[]): string[] {
  const assets = new Set<string>([
    `Source code (${target.repo})`,
    "Git repository & commit history",
  ]);

  if (files.some((f) => f.path.includes("auth") || f.path.includes("login"))) {
    assets.add("Authentication & session management");
  }
  if (files.some((f) => /database|prisma|sequelize|mongoose|sql/i.test(f.path))) {
    assets.add("Database & persistent data");
  }
  if (files.some((f) => f.path.includes("api") || f.path.includes("route"))) {
    assets.add("HTTP API endpoints");
  }
  if (files.some((f) => f.path.endsWith("Dockerfile") || f.path.includes("docker-compose"))) {
    assets.add("Container runtime & images");
  }
  if (files.some((f) => f.path.endsWith(".tf") || f.path.includes("terraform"))) {
    assets.add("Cloud infrastructure (IaC)");
  }
  if (files.some((f) => /secret|credential|env/i.test(f.path))) {
    assets.add("Secrets & API keys");
  }
  if (target.stack.some((s) => /react|vue|angular/i.test(s))) {
    assets.add("Client-side application & user browsers");
  }

  return [...assets];
}

function inferAttackSurfaces(files: RepoFile[], findings: SastFinding[]): string[] {
  const surfaces = new Set<string>();

  for (const f of files) {
    const p = f.path.toLowerCase();
    if (p.includes("route") || p.includes("controller") || p.includes("api/")) {
      surfaces.add("REST/HTTP API handlers");
    }
    if (p.includes("webhook")) surfaces.add("Webhook endpoints");
    if (p.includes("graphql")) surfaces.add("GraphQL API");
    if (p.includes("upload")) surfaces.add("File upload interface");
    if (p.includes("admin")) surfaces.add("Administration panel");
    if (p.endsWith(".github/workflows")) surfaces.add("CI/CD pipeline");
    if (p.endsWith("dockerfile") || p.includes("docker-compose")) surfaces.add("Container deployment");
    if (p.endsWith(".tf")) surfaces.add("Terraform-managed cloud resources");
  }

  for (const finding of findings) {
    if (finding.category === "Secrets") surfaces.add("Exposed credentials in repository");
    if (finding.category === "Injection") surfaces.add("User input → backend execution path");
    if (finding.category === "SSRF") surfaces.add("Server-side HTTP fetch");
    if (finding.category === "XSS") surfaces.add("Browser-rendered user content");
  }

  if (surfaces.size === 0) surfaces.add("Application source code & dependencies");
  return [...surfaces];
}

function buildAttackPaths(
  findings: SastFinding[],
  surfaces: string[],
): ThreatModel["attackPaths"] {
  const paths: ThreatModel["attackPaths"] = [];

  const hasSecret = findings.some((f) => f.category === "Secrets");
  const hasInjection = findings.some((f) => f.category === "Injection");
  const hasAuth = findings.some((f) => f.category === "Authentication");
  const hasDep = findings.some((f) => f.category === "Dependencies");

  if (hasSecret) {
    paths.push({
      path: "Attacker finds hardcoded secret → accesses production API/database",
      likelihood: "High",
      impact: "Critical",
    });
  }
  if (hasInjection) {
    paths.push({
      path: "Attacker submits malicious input → SQL/command injection → data breach or RCE",
      likelihood: "Medium",
      impact: "Critical",
    });
  }
  if (hasAuth) {
    paths.push({
      path: "Weak JWT/session handling → token forgery → account takeover",
      likelihood: "Medium",
      impact: "High",
    });
  }
  if (hasDep) {
    paths.push({
      path: "Known CVE in dependency → exploit public chain → compromise application",
      likelihood: "Medium",
      impact: "High",
    });
  }
  if (surfaces.includes("CI/CD pipeline")) {
    paths.push({
      path: "Compromise CI workflow → inject malicious build step → supply chain attack",
      likelihood: "Low",
      impact: "Critical",
    });
  }

  if (paths.length === 0) {
    paths.push({
      path: "Reconnaissance → exploit misconfiguration → lateral movement",
      likelihood: "Low",
      impact: "Medium",
    });
  }

  return paths;
}

function prioritizeRisks(findings: SastFinding[]): ThreatModel["prioritizedRisks"] {
  const byCategory = new Map<string, SastFinding[]>();
  for (const f of findings) {
    const list = byCategory.get(f.category) ?? [];
    list.push(f);
    byCategory.set(f.category, list);
  }

  const severityScore: Record<string, number> = {
    critical: 90, high: 70, medium: 45, low: 20, info: 5,
  };

  return [...byCategory.entries()]
    .map(([cat, items]) => {
      const top = items.reduce((max, f) =>
        (severityScore[f.severity] ?? 0) > (severityScore[max.severity] ?? 0) ? f : max,
      items[0]);
      const score = Math.min(100, items.reduce((s, f) => s + (severityScore[f.severity] ?? 0), 0) / items.length);
      return {
        risk: `${cat}: ${items.length} finding(s) — e.g. ${top.title}`,
        score: Math.round(score),
        mitigation: mitigationForCategory(cat),
      };
    })
    .sort((a, b) => b.score - a.score)
    .slice(0, 8);
}

function mitigationForCategory(cat: string): string {
  const map: Record<string, string> = {
    Secrets: "Rotate credentials, use secret manager, add pre-commit hooks",
    Injection: "Parameterized queries, input validation, output encoding",
    Authentication: "Verify JWT signatures, rotate secrets, enforce expiry",
    Dependencies: "Upgrade packages, enable Dependabot/Snyk, pin versions",
    XSS: "Sanitize output, CSP headers, avoid innerHTML",
    Configuration: "Harden defaults, environment-specific configs",
    Infrastructure: "Restrict security groups, least-privilege IAM",
    Container: "Non-root user, minimal base image, scan images",
    Cryptography: "Use bcrypt/argon2, crypto.randomBytes for tokens",
    SSRF: "URL allowlists, block internal IPs, network segmentation",
    "Access Control": "Path canonicalization, chroot/jail file access",
    Transport: "Enforce TLS verification, certificate pinning",
  };
  return map[cat] ?? "Review finding details and apply secure coding practices";
}
