import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import type { CodePatch } from "@/lib/ai-assessment/types";
import { Copy, ExternalLink, GitPullRequest } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

export function PatchPreview({
  patches,
  prTitle,
  prBody,
  prUrl,
}: {
  patches: CodePatch[];
  prTitle: string;
  prBody: string;
  prUrl?: string;
}) {
  const { toast } = useToast();

  const copyPr = () => {
    navigator.clipboard.writeText(`# ${prTitle}\n\n${prBody}`);
    toast({ title: "PR description copied" });
  };

  if (patches.length === 0 && !prBody) {
    return (
      <Card>
        <CardContent className="py-8 text-center text-sm text-slate-500">
          No patches generated. Run a full scan with LLM enabled for auto-remediation.
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-4">
      <Card className="border-violet-500/20 bg-violet-500/5">
        <CardHeader className="pb-2">
          <CardTitle className="text-sm flex items-center gap-2">
            <GitPullRequest className="h-4 w-4 text-violet-400" />
            Pull request ready
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          <p className="text-sm font-medium text-slate-200">{prTitle}</p>
          <div className="flex flex-wrap gap-2">
            {prUrl && (
              <Button size="sm" variant="default" asChild>
                <a href={prUrl} target="_blank" rel="noopener noreferrer">
                  <ExternalLink className="h-4 w-4 mr-1.5" /> Open PR on GitHub
                </a>
              </Button>
            )}
            <Button size="sm" variant="outline" onClick={copyPr}>
              <Copy className="h-4 w-4 mr-1.5" /> Copy PR description
            </Button>
          </div>
        </CardContent>
      </Card>

      {patches.map((patch) => (
        <Card key={patch.id}>
          <CardHeader className="pb-2">
            <div className="flex items-start justify-between gap-2">
              <CardTitle className="text-sm">{patch.title}</CardTitle>
              <Badge variant="outline" className="font-mono text-[10px]">{patch.file}</Badge>
            </div>
            <p className="text-xs text-slate-500">{patch.description}</p>
          </CardHeader>
          <CardContent className="space-y-2">
            {patch.rootCause && (
              <p className="text-xs text-slate-400"><span className="text-slate-500">Root cause:</span> {patch.rootCause}</p>
            )}
            {patch.secureAlternative && (
              <p className="text-xs text-emerald-400/80"><span className="text-slate-500">Best practice:</span> {patch.secureAlternative}</p>
            )}
            {patch.diff && (
              <pre className="text-[11px] bg-black/40 rounded-lg p-3 overflow-x-auto font-mono text-slate-300 border border-white/5">
                {patch.diff}
              </pre>
            )}
            <Button
              size="sm"
              variant="ghost"
              className="text-xs"
              onClick={() => {
                navigator.clipboard.writeText(patch.diff);
                toast({ title: "Patch diff copied" });
              }}
            >
              <Copy className="h-3.5 w-3.5 mr-1" /> Copy diff
            </Button>
          </CardContent>
        </Card>
      ))}
    </div>
  );
}
